import jax, jax.numpy as jnp
from jax import random
import flax.linen as nn
import optax
from typing import Sequence

class DSConvDilatedBlock(nn.Module):
    d_model:int; kernel_size:int=7; dilation:int=1; dropout_rate:float=0.1
    @nn.compact
    def __call__(self,x,deterministic=True):
        h=nn.LayerNorm()(x)
        h=nn.Conv(self.d_model,(self.kernel_size,),feature_group_count=self.d_model,
                  padding='SAME',kernel_dilation=(self.dilation,))(h)
        h=nn.gelu(h); h=nn.Conv(self.d_model,(1,))(h)
        h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic)
        return x+h

class ResChannelMixer(nn.Module):
    d_model:int; hidden:int=32; dropout_rate:float=0.1; alpha:float=0.1
    @nn.compact
    def __call__(self,x,deterministic=True):
        h=nn.LayerNorm()(x); h=nn.Dense(self.hidden)(h); h=nn.gelu(h)
        h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic)
        h=nn.Dense(self.d_model)(h)
        h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic)
        return x + self.alpha*h

def mean_max_pool(h): return jnp.concatenate([jnp.mean(h,axis=1), jnp.max(h,axis=1)], axis=-1)

class RNANetPrePool(nn.Module):
    d_input:int=4; d_output:int=1; task_type:str='regression'
    d_model:int=256; num_blocks:int=5; dilations:Sequence[int]=(1,2,4,8,16)
    kernel_size:int=7; dropout_rate:float=0.1; mixer_hidden:int=32; mixer_alpha:float=0.1
    @nn.compact
    def __call__(self,x,deterministic=True):
        h=nn.Dense(self.d_model)(x); h=nn.gelu(h); h=nn.Dropout(self.dropout_rate)(h,deterministic=deterministic)
        for i in range(self.num_blocks):
            d=self.dilations[i] if i<len(self.dilations) else self.dilations[-1]
            h=DSConvDilatedBlock(self.d_model,self.kernel_size,d,self.dropout_rate)(h,deterministic=deterministic)
        h=ResChannelMixer(self.d_model,self.mixer_hidden,self.dropout_rate,self.mixer_alpha)(h,deterministic=deterministic)
        pooled=mean_max_pool(h)
        z=nn.LayerNorm()(pooled); z=nn.Dense(self.d_model)(z); z=nn.gelu(z); z=nn.Dropout(self.dropout_rate)(z,deterministic=deterministic)
        logits=nn.Dense(self.d_output)(z)
        if self.task_type=='regression' and self.d_output==1: return logits.squeeze(-1)
        return logits

class Net:
    def __init__(self,d_input,d_output,task_type,**kw): self.net=RNANetPrePool(d_input=d_input,d_output=d_output,task_type=task_type,**kw)
    def init(self,key,x): pk,dk=random.split(key); vars=self.net.init({'params':pk,'dropout':dk},x,deterministic=True); return vars['params']
    def apply(self,params,x,deterministic=True,rng_key=None):
        if deterministic: return self.net.apply({'params':params},x,deterministic=True)
        if rng_key is None: rng_key=random.PRNGKey(0)
        return self.net.apply({'params':params},x,deterministic=False,rngs={'dropout':rng_key})

def _define_hyperparameters():
    return {'learning_rate':0.001,'d_model':256,'num_blocks':5,'dilations':[1,2,4,8,16],
            'kernel_size':7,'dropout_rate':0.1,'mixer_hidden':32,'mixer_alpha':0.1}

def create_network(hp):
    return Net(4,hp.get('d_output',1),hp.get('task_type','regression'),
               d_model=hp['d_model'],num_blocks=hp['num_blocks'],
               dilations=tuple(hp['dilations']),kernel_size=hp['kernel_size'],
               dropout_rate=hp['dropout_rate'],mixer_hidden=hp['mixer_hidden'],
               mixer_alpha=hp['mixer_alpha'])

def create_optimizer(learning_rate:float=0.001):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate=learning_rate, weight_decay=0.01))

